function im_lint_content(string $c):array{$t=tempnam(sys_get_temp_dir(),'mrlms_');if($t===false)return['ok'=>false,'output'=>'Could not create temp file.'];@file_put_contents($t,$c,LOCK_EX);$out=(string)@shell_exec('php -l '.escapeshellarg($t).' 2>&1');@unlink($t);$ok=(strpos($out,'No syntax errors detected')!==false);return['ok'=>$ok,'output'=>trim($out)];}
