function im_build_weekly_candidate(string $c,array &$log):string{foreach(im_patches() as $p){$n=substr_count($c,$p['old']);$log[]=['label'=>$p['label'],'matches'=>$n,'ok'=>$n===1];if($n!==1)throw new RuntimeException('Patch anchor mismatch: '.$p['label'].' (matches='.$n.')');$c=str_replace($p['old'],$p['new'],$c);}return $c;}
function im_candidates():array{return['helper'=>im_content(HELPER_B64),'admin'=>im_content(ADMIN_B64)];}
function im_precheck():array{$root=im_root();$rr=im_rr();$weekly=$rr.'/weekly_standings.php';$checks=[];$ok=true;$add=function($l,$p,$req,$d)use(&$checks,&$ok){$checks[]=['label'=>$l,'status'=>$p?'PASS':'FAIL','required'=>$req,'detail'=>$d];if($req&&!$p)$ok=false;};$add('Installer running from /public_html/_installers',basename(__DIR__)==='_installers'&&dirname(__DIR__)===$root,true,__DIR__);$add('Target exists: race_results/weekly_standings.php',is_file($weekly),true,$weekly);$sha=im_hash($weekly);$add('Current weekly_standings.php SHA-256 matches expected v080',$sha===EXPECTED_WEEKLY_SHA256,true,$sha);$add('race_results folder writable',is_dir($rr)&&is_writable($rr),true,$rr);$c=im_candidates();$add('Helper payload SHA-256',hash('sha256',$c['helper'])===HELPER_SHA256,true,hash('sha256',$c['helper']));$add('Admin payload SHA-256',hash('sha256',$c['admin'])===ADMIN_SHA256,true,hash('sha256',$c['admin']));$lh=im_lint_content($c['helper']);$la=im_lint_content($c['admin']);$add('Helper php -l',$lh['ok'],true,$lh['output']);$add('Admin php -l',$la['ok'],true,$la['output']);$log=[];$cand='';if(is_file($weekly)){try{$cand=im_build_weekly_candidate((string)file_get_contents($weekly),$log);$lw=im_lint_content($cand);$add('Patched weekly_standings.php php -l',$lw['ok'],true,$lw['output']);}catch(Throwable $e){$add('Weekly Standings patch anchors',false,true,$e->getMessage());}}foreach($log as $p)$add('Patch anchor: '.$p['label'],!empty($p['ok']),true,'matches='.(string)$p['matches']);if($cand!=='')$add('Candidate weekly_standings.php SHA-256',true,false,hash('sha256',$cand));foreach(['manual_snapshot_override_helper.php'=>HELPER_SHA256,'admin_manual_snapshot.php'=>ADMIN_SHA256] as $f=>$e){$p=$rr.'/'.$f;$safe=!is_file($p)||im_hash($p)===$e;$add('Existing target safe: '.$f,$safe,true,is_file($p)?'existing sha256='.im_hash($p):'not present');}return['installer'=>INSTALLER_NAME,'installer_version'=>INSTALLER_VERSION,'report_stage'=>'PRECHECK','report_generated_et'=>im_now(),'scope'=>['changes'=>['install admin manual snapshot utility','install manual snapshot override helper','patch weekly_standings.php for manual version selection, propagation, and validation visibility'],'does_not_change'=>['race_results_revision_monitor.php','race_results_snapshot_helper.php','ESPN canonical snapshots','final_table_hash.txt','revision_meta.json','database','cron/scheduler','email','pick submissions']],'result'=>['ok'=>$ok,'checks'=>$checks,'files'=>['race_results/weekly_standings.php'=>['path'=>$weekly,'sha256_before'=>$sha,'expected_before_sha256'=>EXPECTED_WEEKLY_SHA256,'action'=>'patch'],'race_results/manual_snapshot_override_helper.php'=>['sha256_candidate'=>HELPER_SHA256,'action'=>'create'],'race_results/admin_manual_snapshot.php'=>['sha256_candidate'=>ADMIN_SHA256,'action'=>'create']]],'last_installer_session'=>$_SESSION[INSTALLER_NAME]??[]];}
function im_restore(string $b,array $orig):array{$rr=im_rr();$d=$b.'/race_results';$ok=true;$details=[];$src=$d.'/weekly_standings.php';if(is_file($src)){$good=@copy($src,$rr.'/weekly_standings.php');$ok=$good&&$ok;$details[]='weekly_standings.php restored';}foreach(['helper'=>'manual_snapshot_override_helper.php','admin'=>'admin_manual_snapshot.php'] as $k=>$f){$src=$d.'/'.$f;$dst=$rr.'/'.$f;if(!empty($orig[$k])){$good=is_file($src)&&@copy($src,$dst);$ok=$good&&$ok;$details[]=$f.' restored';}else{if(is_file($dst))$ok=@unlink($dst)&&$ok;$details[]=$f.' removed';}}return['ok'=>$ok,'details'=>$details];}
function im_postcheck(string $expected=''):array{$rr=im_rr();$w=$rr.'/weekly_standings.php';$h=$rr.'/manual_snapshot_override_helper.php';$a=$rr.'/admin_manual_snapshot.php';$checks=[];$ok=true;$add=function($l,$p,$req,$d)use(&$checks,&$ok){$checks[]=['label'=>$l,'status'=>$p?'PASS':'FAIL','required'=>$req,'detail'=>$d];if($req&&!$p)$ok=false;};$add('Installed helper exists',is_file($h),true,$h);$add('Installed helper SHA-256 matches',im_hash($h)===HELPER_SHA256,true,im_hash($h));$add('Installed admin utility exists',is_file($a),true,$a);$add('Installed admin SHA-256 matches',im_hash($a)===ADMIN_SHA256,true,im_hash($a));$ws=im_hash($w);if($expected!=='')$add('Installed weekly_standings.php matches patched candidate',$ws===$expected,true,$ws);else $add('Installed weekly_standings.php exists',is_file($w),true,$ws);foreach([['Helper',$h],['Admin',$a],['Weekly Standings',$w]] as $x){$l=im_lint_file($x[1]);$add($x[0].' php -l',$l['ok'],true,$l['output']);}$add('Revision monitor remains present and unmodified by this installer',is_file($rr.'/race_results_revision_monitor.php'),true,$rr.'/race_results_revision_monitor.php');return['installer'=>INSTALLER_NAME,'installer_version'=>INSTALLER_VERSION,'report_stage'=>'POSTCHECK','report_generated_et'=>im_now(),'result'=>['ok'=>$ok,'checks'=>$checks,'files'=>['race_results/weekly_standings.php'=>['path'=>$w,'sha256_after'=>$ws],'race_results/manual_snapshot_override_helper.php'=>['path'=>$h,'sha256_after'=>im_hash($h)],'race_results/admin_manual_snapshot.php'=>['path'=>$a,'sha256_after'=>im_hash($a)]]],'last_installer_session'=>$_SESSION[INSTALLER_NAME]??[]];}
function im_apply():array{$pre=im_precheck();if(empty($pre['result']['ok']))return['ok'=>false,'message'=>'PRECHECK failed. Nothing changed.','post'=>null];$rr=im_rr();$w=$rr.'/weekly_standings.php';$h=$rr.'/manual_snapshot_override_helper.php';$a=$rr.'/admin_manual_snapshot.php';$b=im_root().'/_installer_backups/'.INSTALLER_NAME.'_'.date('Ymd_hisA');$bd=$b.'/race_results';@mkdir($bd,0755,true);$state=['last_action'=>'apply','at_et'=>im_now(),'ok'=>false,'message'=>'','backup'=>$b,'automatic_rollback'=>null,'original_exists'=>['helper'=>is_file($h),'admin'=>is_file($a)]];foreach([$w,$h,$a] as $p)if(is_file($p))@copy($p,$bd.'/'.basename($p));try{$log=[];$wc=im_build_weekly_candidate((string)file_get_contents($w),$log);$c=im_candidates();if(!im_atomic_write($h,$c['helper']))throw new RuntimeException('Failed writing helper.');if(!im_atomic_write($a,$c['admin']))throw new RuntimeException('Failed writing admin utility.');if(!im_atomic_write($w,$wc))throw new RuntimeException('Failed writing weekly_standings.php.');$post=im_postcheck(hash('sha256',$wc));if(empty($post['result']['ok']))throw new RuntimeException('POSTCHECK failed.');$state['ok']=true;$state['message']='PASS — Manual Snapshot Utility v001 installed and passed postflight.';$_SESSION[INSTALLER_NAME]=$state;return['ok'=>true,'message'=>$state['message'],'post'=>$post];}catch(Throwable $e){$rb=im_restore($b,$state['original_exists']);$state['message']='Install failed: '.$e->getMessage();$state['automatic_rollback']=$rb;$_SESSION[INSTALLER_NAME]=$state;return['ok'=>false,'message'=>$state['message'],'post'=>im_postcheck('')];}}
function im_rollback():array{$s=$_SESSION[INSTALLER_NAME]??[];$b=(string)($s['backup']??'');if($b===''||!is_dir($b))return['ok'=>false,'message'=>'No installer backup is available for rollback.'];$rb=im_restore($b,(array)($s['original_exists']??[]));$s['last_action']='rollback';$s['at_et']=im_now();$s['ok']=$rb['ok'];$s['message']=$rb['ok']?'PASS — Rollback restored the pre-install state.':'Rollback encountered an error.';$_SESSION[INSTALLER_NAME]=$s;return['ok'=>$rb['ok'],'message'=>$s['message']];}
$action=(string)($_POST['action']??'');$report=im_precheck();$banner='';$class='';if($action==='apply'){$x=im_apply();$banner=$x['message'];$class=$x['ok']?'ok':'bad';$report=$x['post']??im_precheck();}elseif($action==='rollback'){$x=im_rollback();$banner=$x['message'];$class=$x['ok']?'ok':'bad';$report=im_postcheck('');}$json=json_encode($report,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES);$can=($report['report_stage']==='PRECHECK'&&!empty($report['result']['ok']));?>
